from time import sleep
import re

from moler.util.moler_test import MolerTest
from moler.exceptions import CommandFailure, CommandTimeout
from taf.ul.sc.generic_functionality import GenericFunctionality
from taf.ul.sc.uesim.synchronize_enb import SynchronizeEnb
from taf.ul.sc.uesim.scenario_duration import ScenarioDuration
from taf.ul.sc.uesim.mapped_sectors import MappedSectors
from taf.ul.sc.uesim.update_and_wait_until_up import UpdateAndWaitUntilUp


class GenericExecutor(GenericFunctionality):
    """Class with keywords for Generic Executor console."""

    basic_state = 'RTG'

    def __init__(self,
                 device_name='RTG',     # type: 'Optional[str]'
                 device=None,           # type: 'Optional[RTG]'
                 autoconnect=False,     # type: 'Optional[bool]'
                 get_device=False       # type: 'Optional[bool]'
                 ):

        super(GenericExecutor, self).__init__(device_name=device_name, device=device,
                                              autoconnect=autoconnect, get_device=get_device)

        self._config = None
        self._version = None
        self._mapped_sectors = None

        self.observers = {}

        if autoconnect:
            self.connect_to_executor()

    def goto_basic_state(self):
        self.device.goto_state(state=self.basic_state)

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_executor(self):
        """
        Connect to executor.
        :return: None
        """
        self.connect()
        self.device.goto_state(state=self.basic_state)

        MolerTest.steps_end()

    def update_local_configuration(self, timeout=60, path=None):
        """Keyword for updating local configuration.
        This need to be executed after each configuration change.

        :param timeout: command execution timeout
        :param path: path to ini file
        """
        self.goto_basic_state()
        if path:
            config_update_cmd = self.device.get_cmd(cmd_name="config_update", cmd_params={"path": path})
        else:
            config_update_cmd = self.device.get_cmd(cmd_name="config_update")
        try:
            config_update_cmd(timeout=timeout)
        except CommandFailure as err:
            # Ignore errors in case of ERROR in added/changed/removed while this is parameter value
            if not re.search(r"(added|changed|removed).*:.*ERROR", err):
                raise err
            else:
                pass
        MolerTest.sleep(10)

    def update_remote_configuration(self, target='', timeout=300):
        """Keyword for sending local configuration to RTG components.
        This cause sending configuration and reboot of all controllers.

        :param target: you can specify target to which configuration will be sent
        :param timeout: command execution timeout
        """
        self.goto_basic_state()
        config_remote_update_cmd = self.device.get_cmd(cmd_name="config_remote_update",
                                                       cmd_params={"options": target})
        config_remote_update_cmd(timeout=timeout)

    def reload_remote_configuration(self, target='', timeout=600):
        """Keyword for reload controllers' software images on RTG.
        This cause reload and reboot on all controllers.

        :param target: you can specify target on which controllers reload will be performed
        :param timeout: command execution timeout
        """
        self.goto_basic_state()
        config_remote_reload_cmd = self.device.get_cmd(cmd_name="config_remote_reload",
                                                       cmd_params={"options": target})
        config_remote_reload_cmd(timeout=timeout)

    def align_rtg_cell_to_small_cell(self, timeout=120):
        """Keyword for aligning rtg cell to small cell.
        This command need to be executed after each RTG reboot in case of Small Cell eNB and using digital domain.

        :param timeout: command execution timeout
        """
        self.goto_basic_state()
        fzm_align_command = self.device.get_cmd(cmd_name="config_remote_fzmalign")
        fzm_align_command(timeout=timeout)

    def align_rtg_cell_to_lbr_device(self, target='', timeout=120):
        """
        This Keyword is for aligning rtg with LBR device connected between it and eNB cell.

        :param target: target cell if not passed then all LBR devices will be aligned
        :param timeout: command execution timeout
        :return:
        """
        self.goto_basic_state()
        options = {"target": target}
        config_remote_lbralign_command = self.device.get_cmd(cmd_name="config_remote_lbralign", cmd_params=options)
        config_remote_lbralign_command(timeout=timeout)

    def align_rtg_cell_to_radio_cell(self, target='', timeout=120, retries=3):
        """
        Keyword for aligning RTG cell to eNB cell.
        This command need to be executed when in setup there is RF cell.

        :param target: optional parameter where you can specify cell to align
        :param timeout: command execution timeout
        :param retries: number of retries in case of failure
        :return:
        """
        self.goto_basic_state()

        for try_number in range(retries):
            try:
                config_remote_fzmrfconfig_command = self.device.get_cmd(cmd_name="config_remote_fzmrfconfig",
                                                                        cmd_params={"target": target})
                config_remote_fzmrfconfig_command(timeout=timeout)
                break
            except (CommandTimeout, CommandFailure):
                sleep(300)
                continue

    def remote_restart(self, target='', timeout=120):
        """
        Keyword for restart passed devices in target parameter.

        :param target: optional parameter where you can specify device to restart.
                       If not set all devices will be restarted
        :param timeout: command execution timeout
        :return:
        """
        self.goto_basic_state()
        config_remote_restart_command = self.device.get_cmd(cmd_name="config_remote_restart",
                                                            cmd_params={"target": target})
        config_remote_restart_command(timeout=timeout)

    def start_rtg_scenario(self, scenario_name="attach", timeout=300):
        """This keyword is used for starting scenario

        :param scenario_name - name of scenario file without .scn extension
        :param timeout: command execution timeout
        """
        self.goto_basic_state()
        start_scenario_cmd = self.device.get_cmd(cmd_name="start", cmd_params={"scenario": scenario_name})
        result = start_scenario_cmd(timeout=timeout)
        return result

    def stop_rtg_scenario(self, timeout=180):
        """This keyword is used for stopping scenario.

        :param timeout: command execution timeout
        """
        self.goto_basic_state()
        stop_scenario_cmd = self.device.get_cmd(cmd_name="stop")
        stop_scenario_cmd(timeout=timeout)

    def start_ue_session(self, mobile_session, timeout=60, **kwargs):
        """
        Keyword for starting new mobileSession during test using 'scenario ue start' command

        :param mobile_session: name of the mobile session
        :param timeout: command execution timeout
        :param kwargs: 'scenario ue start' command parameters
        :return: boolean
        """
        self.goto_basic_state()
        scenario_ue_start = self.device.get_cmd(cmd_name="scenario_ue_start",
                                                cmd_params={"mobile_session": mobile_session,
                                                            "parameters": kwargs})
        return scenario_ue_start(timeout=timeout)

    def stop_ue_session(self, ids, detach=False, timeout=60):
        """
        Keyword for stopping mobileSession during test using 'scenario ue stop' command

        :param mobile_session: name of the mobile session
        :param timeout: command execution timeout
        :param args: 'scenario ue stop' command parameters
        :return: boolean
        """
        self.goto_basic_state()
        scenario_ue_stop = self.device.get_cmd(cmd_name="scenario_ue_stop",
                                               cmd_params={"ids": ids, "detach": detach})
        return scenario_ue_stop(timeout=timeout)

    def synchronize_small_cell_link(self, enbs=[], attempts=3):
        """
        This keyword is used for synchronization link between rtg and enb

        :param enbs: list of enb devices --> each should be class of ta_moler.device.fzm_console.FzmConsole
        :param attempts: number of attempts, default 3
        :return: boolean
        """
        SynchronizeEnb(self).synchronize_small_cell_link(enbs, attempts)

    def clean_logs_directory(self, timeout=120):
        """
        Keyword for cleaning default logs directory.

        :param timeout: command execution timeout
        :return:
        """
        self.goto_basic_state()
        stats_cleanlogdir = self.device.get_cmd(cmd_name="stats_cleanlogdir")
        stats_cleanlogdir(timeout=timeout)

    def restart_mbms_statistics(self, timeout=120):
        """
        Keyword for restarting mbms statistics.

        :param timeout: command execution timeout
        :return:
        """
        self.goto_basic_state()
        stats_mbms_restart = self.device.get_cmd(cmd_name="stats_mbms",
                                                 cmd_params={"options": 'reset'})
        stats_mbms_restart(timeout=timeout)

    def get_mbms_statistics(self, timeout=120):
        """
        Keyword for obtaining collected mbms statistics.

        :param timeout: command execution timeout
        :return:
        """
        self.goto_basic_state()
        stats_mbms = self.device.get_cmd(cmd_name="stats_mbms")
        return stats_mbms(timeout=timeout)

    @property
    def config(self):
        if self._config is None:
            self.get_configuration()
        return self._config

    def get_configuration(self, options=None):
        """Keyword for getting configuration.

        :param options: You can add options which filter output of command
        :return: Configuration of the device
        """
        self.goto_basic_state()
        config_list_cmd = self.device.get_cmd(cmd_name="config_list", cmd_params={"options": options})
        self._config = config_list_cmd(timeout=60)
        return self._config

    def is_rf_cell_in_configuration(self):
        """
        Keyword for checking if RF cell is in configuration.
        :return: True if RF cell is in configuration, False otherwise
        """
        self.goto_basic_state()
        try:
            self.get_configuration(options="fzm_rf")
        except (CommandFailure, CommandTimeout):
            return False
        return True

    @property
    def version(self):
        if self._version is None:
            self.get_version()
        return self._version

    def get_version(self):
        """Keyword for getting build version.

        :return: Build version
        """
        self.goto_basic_state()
        version_cmd = self.device.get_cmd(cmd_name='version')
        self._version = version_cmd(timeout=60)['BUILD']
        return self._version

    def get_ctrls(self):
        """Keyword for getting controls configurations.

        :return: Return controls configurations.
        """
        return self.config.get('ctrl')

    def get_tgrs(self):
        """Keyword for getting TGRs configurations.

        :return: Return TGRs configurations.
        """
        return self.config.get('tgr')

    def get_sectors(self):
        """Keyword for getting sectors configurations.

        :return: Return sectors configurations.
        """
        return self.config.get('sector')

    def get_ltu_sectors(self):
        """Keyword for getting ltu sectors configurations.

        :return: Return ltu sectors configurations.
        """
        sectors = self.get_sectors()
        ltu_sectors = {number: sectors[number] for number in sectors if sectors[number].get('ecsat_lte_u') == 'on'}
        return ltu_sectors if len(ltu_sectors) != 0 else None

    def get_status(self, options=None):
        """Keyword for getting status of executed scenarios.

        :param options: You can specify options for command to chose list qeue|history|error|all and number of results.
        :return: Status of scenarios execution
        """
        self.goto_basic_state()
        status_cmd = self.device.get_cmd(cmd_name='status', cmd_params={'options': options})
        status = status_cmd(timeout=60)
        return status

    def get_current_scenario_duration(self):
        """Keyword for getting duration of current scenario.

        :return: If scenario is running duration of the scenario otherwise None
        """
        return ScenarioDuration(self).get_current_scenario_duration()

    def get_last_scenario_duration(self):
        """Keyword for getting last scenario duration.

        :return: Last scenario duration. If last scenario was with error or doesn't exist returns None
        """
        return ScenarioDuration(self).get_last_scenario_duration()

    def connect_all_devices(self, timeout=120):
        """Keyword for executing sector/tgr connect procedure.

        :param timeout: command execution timeout
        :return: None
        """
        self.goto_basic_state()
        cm_connect_cmd = self.device.get_cmd(cmd_name='cm_connect')
        cm_connect_cmd(timeout=timeout)

    def disconnect_all_devices(self, timeout=120):
        """
        Keyword for executing sector/tgr disconnect procedure.

        :param timeout: command execution timeout
        :return: Nothing
        """
        self.goto_basic_state()
        cm_disconnect_cmd = self.device.get_cmd(cmd_name='cm_disconnect')
        cm_disconnect_cmd(timeout=timeout)

    @property
    def mapped_sectors(self):
        if self._mapped_sectors is None:
            self._mapped_sectors = MappedSectors(self).get_mapped_sectors()
        return self._mapped_sectors

    def start_sync_lost_observer(self):
        """Keyword for starting sync lost observers.

        :return: None
        """
        self.observers['device_connection_lost'] = self.device.get_event(event_name="device_connection_lost",
                                                                         event_params={"till_occurs_times": 1})
        self.observers['sectors_inoperational'] = self.device.get_event(event_name="sectors_inoperational",
                                                                        event_params={"till_occurs_times": 1})
        self.observers['sector_not_receiving_ovhd'] = self.device.get_event(event_name="sector_not_receiving_ovhd",
                                                                            event_params={"till_occurs_times": 1})
        self.observers['dsp_crash'] = self.device.get_event(event_name="dsp_crash",
                                                            event_params={"till_occurs_times": 1})
        for observer in self.observers.values():
            observer.start()

    def cancel_sync_lost_observer(self):
        """Keyword for canceling all observers.

        :return: None
        """
        for observer in self.observers.values():
            observer.cancel()
        self.observers = {}

    def config_remote_update_and_synchronize_enb(self, workstation, ctrls=[], enbs=[]):
        """Keyword for restarting controllers and synchronizing rtg and enbs.

        :param ctrls: list of ctrl devices --> each should be class of taf.ul.sc.rtg.controller.Controller
        :param enbs: list of enb devices --> each should be class of ta_moler.device.fzm_console.FzmConsole
        :return: None
        """
        cru = UpdateAndWaitUntilUp(executor=self, workstation=workstation, ctrls=ctrls)
        cru.config_remote_update_and_wait_until_controllers_up()
        self.synchronize_small_cell_link(enbs)

    def get_enbsim_ctrls(self):
        """
        Get list of ctrls which are configured as ENBSIM
        :return: list of ctrls
        """

        return self._get_ctrls_with_attribute_set_to(attribute='hardware_platform', value='ENBSIM')

    def get_endc_wts(self):
        """
        Get list of endc wts cells
        :return: list of dictionaries
        """
        self.goto_basic_state()
        cmd = self.device.get_cmd(cmd_name="display_endc_wts")
        return cmd(timeout=60)

    def _get_ctrls_with_attribute_set_to(self, attribute, value):
        """
        Get list of ctrls with attribute set to passed value
        eg:
        [ctrl 12]
        hardware_platform      = ENBSIM

        In above example attribute is hardware_platform and value is ENBSIM

        :param attribute: attribute name
        :param value: value of attribute
        :return: list of ctrl with attribute set to passed value
        """
        config = self.get_configuration()
        ctrls = []

        for ctrl_id in config['ctrl']:
            _value = config['ctrl'][ctrl_id].get(attribute, None)
            if _value and _value.upper() == value.upper():
                ctrls.append(ctrl_id)

        return ctrls
